def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    # Find 3-cell L components; recolor the one matching the color-1 L motif.
    # Matching allows rotations/reflections, and picks the non-1 occurrence.
    seen=set()
    comps=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col in (9,0) or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((col,cells))
    target=None
    for col,cells in comps:
        if col==1 and len(cells)==3:
            target={ (y-min(y for y,x in cells),x-min(x for y,x in cells)) for y,x in cells }
            break
    if target:
        for col,cells in comps:
            if col==1 or len(cells)!=3: continue
            norm={(y-min(y for y,x in cells),x-min(x for y,x in cells)) for y,x in cells}
            variants=[]
            for flip in (1,-1):
                pts=[(y,x*flip) for y,x in norm]
                for k in range(4):
                    if k: pts=[(x,-y) for y,x in pts]
                    variants.append({(y-min(a for a,b in pts),x-min(b for a,b in pts)) for y,x in pts})
            if target in variants:
                for y,x in cells: out[y][x]=1
                break
    return out
